    /// The layout that a `Reserved` is written and read in
    @inlinable
    public static var layout: TableLayout { TableLayout.default }

    @usableFromInline
    let _reader: TableReader

    /// Reads a `Reserved` from `bytes`, which it can't outlive
    @inlinable
    @_lifetime(copy bytes)
    public init(_ bytes: RawSpan) {
        _reader = TableReader(bytes, layout: Self.layout)
    }

    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var keywords: Keywords {
        @_lifetime(copy self)
        get throws(DecodeError) {
            let field = try _reader.rootOffset(0)
            return Keywords(reader: _reader, position: field)
        }
    }
}

/// The fields of a `Reserved`, to write
public struct ReservedFields: Hashable, Sendable {
    public var keywords: KeywordsFields

    public init(keywords: KeywordsFields) {
        self.keywords = keywords
    }

    /// Writes a `Reserved` with every field.
    ///
    /// Throws a `BuildError` if it's longer than its offset type, `uint32`, addresses.
    public func serialize() throws(BuildError) -> [UInt8] {
        var sizer = try TableSizer(fields: 1, layout: Reserved.layout)
        sizer.addTable(alignment: KeywordsFields.alignment)
        self.keywords.add(to: &sizer)

        return try sizer.bytes { writer in
            writer.setTable(0, alignment: KeywordsFields.alignment)
            self.keywords.write(to: &writer)
        }
    }
}

/// Structs as fields, in place like scalars, and in arrays, which are aligned
/// to their structs' largest scalar
@frozen
public struct Structs: ~Escapable {
    /// The layout that a `Structs` is written and read in
    @inlinable
    public static var layout: TableLayout { TableLayout.default }

    @usableFromInline
    let _reader: TableReader

    /// Reads a `Structs` from `bytes`, which it can't outlive
    @inlinable
    @_lifetime(copy bytes)
    public init(_ bytes: RawSpan) {
        _reader = TableReader(bytes, layout: Self.layout)
    }

    /// A struct of every scalar type
    ///
    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var packed: Packed {
        get throws(DecodeError) {
            let field = try _reader.rootOffset(0)
            return try Packed(_reader.struct(at: field, size: Packed.size), at: 0)
        }
    }

    /// An array of structs of 7 bytes, aligned to 4
    ///
    /// A view of the structs, which reads each `Documented` when it's asked for.
    ///
    /// Throws a `DecodeError` if the field, or its structs, lie outside the bytes.
    @inlinable
    public var documented: DocumentedArray {
        @_lifetime(copy self)
        get throws(DecodeError) {
            let field = try _reader.rootOffset(1)
            return try DocumentedArray(_reader.structArray(at: field, size: Documented.size))
        }
    }

    /// A struct of structs
    ///
    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var segment: Segment {
        get throws(DecodeError) {
            let field = try _reader.rootOffset(2)
            return try Segment(_reader.struct(at: field, size: Segment.size), at: 0)
        }
    }

    /// A view of the structs, which reads each `Segment` when it's asked for.
    ///
    /// Throws a `DecodeError` if the field, or its structs, lie outside the bytes.
    @inlinable
    public var segments: SegmentArray {
        @_lifetime(copy self)
        get throws(DecodeError) {
            let field = try _reader.rootOffset(3)
            return try SegmentArray(_reader.structArray(at: field, size: Segment.size))
        }
    }

    /// A table nested in the message, which holds structs too
    ///
    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var path: Path {
        @_lifetime(copy self)
        get throws(DecodeError) {
            let field = try _reader.rootOffset(4)
            return Path(reader: _reader, position: field)
        }
    }
}

/// The fields of a `Structs`, to write
public struct StructsFields: Hashable, Sendable {
    /// A struct of every scalar type
    public var packed: Packed
    /// An array of structs of 7 bytes, aligned to 4
    public var documented: [Documented]
    /// A struct of structs
    public var segment: Segment
    public var segments: [Segment]
    /// A table nested in the message, which holds structs too
    public var path: PathFields

    public init(packed: Packed, documented: [Documented], segment: Segment, segments: [Segment], path: PathFields) {
        self.packed = packed
        self.documented = documented
        self.segment = segment
        self.segments = segments
        self.path = path
    }

    /// Writes a `Structs` with every field.
    ///
    /// Throws a `BuildError` if it's longer than its offset type, `uint32`, addresses.
    public func serialize() throws(BuildError) -> [UInt8] {
        var sizer = try TableSizer(fields: 5, layout: Structs.layout)
        sizer.addStruct(size: Packed.size)
        sizer.addStructArray(count: self.documented.count, size: Documented.size, alignment: Documented.alignment)
        sizer.addStruct(size: Segment.size)
        sizer.addStructArray(count: self.segments.count, size: Segment.size, alignment: Segment.alignment)
        sizer.addTable(alignment: PathFields.alignment)
        self.path.add(to: &sizer)

        return try sizer.bytes { writer in
            writer.setStruct(0)
            self.packed.write(to: &writer)
            writer.setStructArray(1, count: self.documented.count, alignment: Documented.alignment)
            for item in self.documented {
                item.write(to: &writer)
            }
            writer.setStruct(2)
            self.segment.write(to: &writer)
            writer.setStructArray(3, count: self.segments.count, alignment: Segment.alignment)
            for item in self.segments {
                item.write(to: &writer)
            }
            writer.setTable(4, alignment: PathFields.alignment)
            self.path.write(to: &writer)
        }
    }
}

@frozen
public struct Path: ~Escapable {
    @usableFromInline
    let _reader: TableReader
    @usableFromInline
    let _position: Int

    /// Reads the table at `position` in the bytes that `reader` reads, as its parent's getter finds it
    @inlinable
    @_lifetime(copy reader)
    init(reader: TableReader, position: Int) {
        _reader = reader
        _position = position
    }

    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var start: Point {
        get throws(DecodeError) {
            let field = try _reader.fieldOffset(0, inTableAt: _position)
            return try Point(_reader.struct(at: field, size: Point.size), at: 0)
        }
    }

    /// A view of the structs, which reads each `Point` when it's asked for.
    ///
    /// Throws a `DecodeError` if the field, or its structs, lie outside the bytes.
    @inlinable
    public var points: PointArray {
        @_lifetime(copy self)
        get throws(DecodeError) {
            let field = try _reader.fieldOffset(1, inTableAt: _position)
            return try PointArray(_reader.structArray(at: field, size: Point.size))
        }
    }
}

/// The fields of a `Path`, to write
public struct PathFields: Hashable, Sendable {
    /// The alignment that a parent pads a `Path` to: the largest alignment of its arrays
    /// and nested tables, or 1
    public static let alignment: Alignment = .four

    public var start: Point
    public var points: [Point]

    public init(start: Point, points: [Point]) {
        self.start = start
        self.points = points
    }

    /// Adds a `Path` to its parent's sizer, after the field or vector that holds it
    public func add(to sizer: inout TableSizer) {
        let parent = sizer.startTable(fields: 2)
        sizer.addStruct(size: Point.size)
        sizer.addStructArray(count: self.points.count, size: Point.size, alignment: Point.alignment)
        sizer.endTable(parent)
    }

    /// Writes a `Path` where its parent's writer is, after the field or vector that holds it
    public func write(to writer: inout TableWriter) {
        let parent = writer.startTable(fields: 2)
        writer.setStruct(0)
        self.start.write(to: &writer)
        writer.setStructArray(1, count: self.points.count, alignment: Point.alignment)
        for item in self.points {
            item.write(to: &writer)
        }
        writer.endTable(parent)
    }
}

/// Two points, whose scalars lie in the segment's place
@frozen
public struct Segment: Hashable, Sendable {
    /// The byte length of a `Segment`
    public static let size = 16
    /// The alignment of an array of `Segment`s: its largest scalar's size
    public static let alignment: Alignment = .four

    public var start: Point
    public var end: Point

    public init(start: Point, end: Point) {
        self.start = start
        self.end = end
    }

    /// Reads a `Segment` from the start of `bytes`.
    ///
    /// Throws a `DecodeError` if `bytes` are shorter than `size`.
    @inlinable
    public init(_ bytes: RawSpan) throws(DecodeError) {
        self.init(try TableReader(bytes).struct(at: 0, size: Self.size), at: 0)
    }

    /// Reads a `Segment` at `offset` in `bytes`, which hold its scalars there
    @inlinable
    init(_ bytes: RawSpan, at offset: Int) {
        self.start = Point(bytes, at: offset)
        self.end = Point(bytes, at: offset + 8)
    }

    /// The bytes of a `Segment`: its scalars, little-endian, one after another
    public func serialize() -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(Self.size)
        self.append(to: &bytes)
        return bytes
    }

    /// The bytes of an array of `Segment`s, as a table holds them: theirs, one after another
    public static func serializeArray(_ items: [Self]) -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(items.count * Self.size)
        for item in items {
            item.append(to: &bytes)
        }
        return bytes
    }

    /// Appends the scalars to `bytes`, little-endian
    func append(to bytes: inout [UInt8]) {
        self.start.append(to: &bytes)
        self.end.append(to: &bytes)
    }

    /// Writes the scalars where `writer` is, little-endian, after the `setStruct(_:)` or the
    /// `setStructArray(_:count:alignment:)` of the field that holds them
    public func write(to writer: inout TableWriter) {
        self.start.write(to: &writer)
        self.end.write(to: &writer)
    }
}

/// An array of `Segment`s, which reads each struct when it's asked for
@frozen
public struct SegmentArray: ~Escapable {
    /// The structs' bytes, one after another
    public let bytes: RawSpan

    @inlinable
    @_lifetime(copy bytes)
    init(_ bytes: RawSpan) {
        self.bytes = bytes
    }

    /// The number of structs
    @inlinable
    public var count: Int { bytes.byteCount / Segment.size }

    @inlinable
    public var isEmpty: Bool { bytes.isEmpty }

    /// The indices of the structs, from 0 to `count`
    @inlinable
    public var indices: Swift.Range<Int> { 0..<count }

    /// Reads struct `index`, which must be one of `indices`: an index outside them is a programming
    /// error, which stops the program, as `Array`'s subscript does.
    @inlinable
    public subscript(index: Int) -> Segment {
        precondition(UInt(bitPattern: index) < UInt(count), "Index out of range")

        // The precondition keeps the struct within the bytes
        let offset = index &* Segment.size
        return Segment(bytes.extracting(unchecked: offset..<offset &+ Segment.size), at: 0)
    }
}

extension Array where Element == Segment {
    /// Reads every struct of an array read from a table, into an array of their own
    @inlinable
    public init(_ view: borrowing SegmentArray) {
        self = view.indices.map { view[$0] }
    }
}

@frozen
public struct Point: Hashable, Sendable {
    /// The byte length of a `Point`
    public static let size = 8
    /// The alignment of an array of `Point`s: its largest scalar's size
    public static let alignment: Alignment = .four

    public var x: Float
    public var y: Float

    public init(x: Float, y: Float) {
        self.x = x
        self.y = y
    }

    /// Reads a `Point` from the start of `bytes`.
    ///
    /// Throws a `DecodeError` if `bytes` are shorter than `size`.
    @inlinable
    public init(_ bytes: RawSpan) throws(DecodeError) {
        self.init(try TableReader(bytes).struct(at: 0, size: Self.size), at: 0)
    }

    /// Reads a `Point` at `offset` in `bytes`, which hold its scalars there
    @inlinable
    init(_ bytes: RawSpan, at offset: Int) {
        self.x = Float(littleEndianBytes: bytes, at: offset)
        self.y = Float(littleEndianBytes: bytes, at: offset + 4)
    }

    /// The bytes of a `Point`: its scalars, little-endian, one after another
    public func serialize() -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(Self.size)
        self.append(to: &bytes)
        return bytes
    }

    /// The bytes of an array of `Point`s, as a table holds them: theirs, one after another
    public static func serializeArray(_ items: [Self]) -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(items.count * Self.size)
        for item in items {
            item.append(to: &bytes)
        }
        return bytes
    }

    /// Appends the scalars to `bytes`, little-endian
    func append(to bytes: inout [UInt8]) {
        withUnsafeBytes(of: self.x.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.y.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
    }

    /// Writes the scalars where `writer` is, little-endian, after the `setStruct(_:)` or the
    /// `setStructArray(_:count:alignment:)` of the field that holds them
    public func write(to writer: inout TableWriter) {
        writer.writeScalar(self.x)
        writer.writeScalar(self.y)
    }
}

