/// A struct of every scalar type and a bool, at fixed offsets without
/// padding
@frozen
public struct Packed: Hashable, Sendable {
    /// The byte length of a `Packed`
    public static let size = 43
    /// The alignment of an array of `Packed`s: its largest scalar's size
    public static let alignment: Alignment = .eight

    public var int8: Int8
    public var uint8: UInt8
    public var int16: Int16
    public var uint16: UInt16
    public var int32: Int32
    public var uint32: UInt32
    public var int64: Int64
    public var uint64: UInt64
    public var float32: Float
    public var float64: Double
    public var bool: Bool

    public init(
        int8: Int8,
        uint8: UInt8,
        int16: Int16,
        uint16: UInt16,
        int32: Int32,
        uint32: UInt32,
        int64: Int64,
        uint64: UInt64,
        float32: Float,
        float64: Double,
        bool: Bool
    ) {
        self.int8 = int8
        self.uint8 = uint8
        self.int16 = int16
        self.uint16 = uint16
        self.int32 = int32
        self.uint32 = uint32
        self.int64 = int64
        self.uint64 = uint64
        self.float32 = float32
        self.float64 = float64
        self.bool = bool
    }

    /// Reads a `Packed` from the start of `bytes`.
    ///
    /// Throws a `DecodeError` if `bytes` are shorter than `size`.
    @inlinable
    public init(_ bytes: RawSpan) throws(DecodeError) {
        self.init(try TableReader(bytes).struct(at: 0, size: Self.size), at: 0)
    }

    /// Reads a `Packed` at `offset` in `bytes`, which hold its scalars there
    @inlinable
    init(_ bytes: RawSpan, at offset: Int) {
        self.int8 = Int8(littleEndianBytes: bytes, at: offset)
        self.uint8 = UInt8(littleEndianBytes: bytes, at: offset + 1)
        self.int16 = Int16(littleEndianBytes: bytes, at: offset + 2)
        self.uint16 = UInt16(littleEndianBytes: bytes, at: offset + 4)
        self.int32 = Int32(littleEndianBytes: bytes, at: offset + 6)
        self.uint32 = UInt32(littleEndianBytes: bytes, at: offset + 10)
        self.int64 = Int64(littleEndianBytes: bytes, at: offset + 14)
        self.uint64 = UInt64(littleEndianBytes: bytes, at: offset + 22)
        self.float32 = Float(littleEndianBytes: bytes, at: offset + 30)
        self.float64 = Double(littleEndianBytes: bytes, at: offset + 34)
        self.bool = UInt8(littleEndianBytes: bytes, at: offset + 42) != 0
    }

    /// The bytes of a `Packed`: its scalars, little-endian, one after another
    public func serialize() -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(Self.size)
        self.append(to: &bytes)
        return bytes
    }

    /// The bytes of an array of `Packed`s, as a table holds them: theirs, one after another
    public static func serializeArray(_ items: [Self]) -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(items.count * Self.size)
        for item in items {
            item.append(to: &bytes)
        }
        return bytes
    }

    /// Appends the scalars to `bytes`, little-endian
    func append(to bytes: inout [UInt8]) {
        bytes.append(UInt8(bitPattern: self.int8))
        bytes.append(self.uint8)
        withUnsafeBytes(of: self.int16.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.uint16.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.int32.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.uint32.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.int64.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.uint64.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.float32.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.float64.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
        bytes.append(self.bool ? 1 : 0)
    }

    /// Writes the scalars where `writer` is, little-endian, after the `setStruct(_:)` or the
    /// `setStructArray(_:count:alignment:)` of the field that holds them
    public func write(to writer: inout TableWriter) {
        writer.writeScalar(self.int8)
        writer.writeScalar(self.uint8)
        writer.writeScalar(self.int16)
        writer.writeScalar(self.uint16)
        writer.writeScalar(self.int32)
        writer.writeScalar(self.uint32)
        writer.writeScalar(self.int64)
        writer.writeScalar(self.uint64)
        writer.writeScalar(self.float32)
        writer.writeScalar(self.float64)
        writer.writeScalar(UInt8(self.bool ? 1 : 0))
    }
}

/// Documentation of several lines.
///
/// It can hold Markdown's `code spans`, non-ASCII text such as å, 世界 and
/// 🦀, and text that closes a comment or string in some language: */, """,
/// a backslash \ and a trailing quote"
///
/// Javadoc and `JSDoc` read it as text, with HTML's <b>, &amp; and &,
/// Javadoc's {@link Object} and `{@code x}`, Java's Unicode escape \u000A,
/// and a tag at the start of a line:
/// @deprecated
@frozen
public struct Documented: Hashable, Sendable {
    /// The byte length of a `Documented`
    public static let size = 7
    /// The alignment of an array of `Documented`s: its largest scalar's size
    public static let alignment: Alignment = .four

    /// A field's documentation, of one line
    public var one: UInt8
    /// A field's documentation,
    /// of two lines
    public var two: UInt16
    public var undocumented: UInt32

    public init(one: UInt8, two: UInt16, undocumented: UInt32) {
        self.one = one
        self.two = two
        self.undocumented = undocumented
    }

    /// Reads a `Documented` from the start of `bytes`.
    ///
    /// Throws a `DecodeError` if `bytes` are shorter than `size`.
    @inlinable
    public init(_ bytes: RawSpan) throws(DecodeError) {
        self.init(try TableReader(bytes).struct(at: 0, size: Self.size), at: 0)
    }

    /// Reads a `Documented` at `offset` in `bytes`, which hold its scalars there
    @inlinable
    init(_ bytes: RawSpan, at offset: Int) {
        self.one = UInt8(littleEndianBytes: bytes, at: offset)
        self.two = UInt16(littleEndianBytes: bytes, at: offset + 1)
        self.undocumented = UInt32(littleEndianBytes: bytes, at: offset + 3)
    }

    /// The bytes of a `Documented`: its scalars, little-endian, one after another
    public func serialize() -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(Self.size)
        self.append(to: &bytes)
        return bytes
    }

    /// The bytes of an array of `Documented`s, as a table holds them: theirs, one after another
    public static func serializeArray(_ items: [Self]) -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(items.count * Self.size)
        for item in items {
            item.append(to: &bytes)
        }
        return bytes
    }

    /// Appends the scalars to `bytes`, little-endian
    func append(to bytes: inout [UInt8]) {
        bytes.append(self.one)
        withUnsafeBytes(of: self.two.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.undocumented.littleEndian) { bytes.append(contentsOf: $0) }
    }

    /// Writes the scalars where `writer` is, little-endian, after the `setStruct(_:)` or the
    /// `setStructArray(_:count:alignment:)` of the field that holds them
    public func write(to writer: inout TableWriter) {
        writer.writeScalar(self.one)
        writer.writeScalar(self.two)
        writer.writeScalar(self.undocumented)
    }
}

